const now = new Date().toISOString();
return [{
  json: {
    workflow: 'PROJETO_SM3_00R_RELIABILITY_SMOKE',
    node: 'SYNTHETIC_FAILURE',
    stage: 'SMOKE_TEST',
    entity_type: 'SYSTEM_TEST',
    entity_id: 'SMOKE_TEST',
    error_code: 'SM3_SYNTHETIC_TEST',
    error_message: 'Evento sintético criado propositalmente para validar o dead-letter local.',
    attempt_count: 3,
    max_tries: 3,
    retryable: false,
    disposition: 'TEST_ONLY',
    execution_id: String($execution.id || ''),
    created_at: now,
    payload: {
      test_only: true,
      expected_contract: 'SM3_RELIABILITY_V1'
    },
    version: 'SM3_RELIABILITY_V1'
  }
}];

const x = $input.first().json;
const ok =
  x.ok === true &&
  x.reliability_contract === 'SM3_RELIABILITY_V1' &&
  x.dead_letter_primary === 'LOCAL_JSONL' &&
  Number(x.event_count || 0) >= 1 &&
  x.file_exists === true;

if (!ok) {
  throw new Error('SM3_RELIABILITY_SMOKE_FAILED: ' + JSON.stringify(x));
}

return [{
  json: {
    status: 'SM3_RELIABILITY_PASS',
    reliability_contract: x.reliability_contract,
    dead_letter_primary: x.dead_letter_primary,
    dead_letter_path: x.dead_letter_path,
    event_count: x.event_count,
    file_bytes: x.file_bytes,
    last_event_id: x.last_event_id,
    checked_at: new Date().toISOString()
  }
}];
